update public.store_settings s
set data = jsonb_set(s.data, '{products}', (
      select jsonb_agg(
        case when d.descr is not null and coalesce(btrim(p->>'description'), '') = ''
             then jsonb_set(p, '{description}', to_jsonb(d.descr))
             else p end
        order by t.ord)
      from jsonb_array_elements(s.data->'products') with ordinality as t(p, ord)
      left join d on d.id = t.p->>'id'
    )),
    version = s.version + 1,
    updated_at = now()
where s.id = true;